    const evOf = (f, k) => k in vals ? vals[k] : f.value || '';
    const isMandatory = f => (f.cat === '*' || f.cat === '‡') && f.source !== 'ENGINE';

    // every editable (non-divider) field key, in order
    const allKeys = useMemo(() => {
      const a = [];
      blocks.forEach(b => b.instances.forEach((inst, ii) => (inst.fields || []).forEach(f => {
        if (!f.divider) a.push(`${b.key}.${ii}.${f.id}`);
      })));
      return a;
    }, [blocks]);
    const fieldByKey = useMemo(() => {
      const m = {};
      blocks.forEach(b => b.instances.forEach((inst, ii) => (inst.fields || []).forEach(f => {
        if (!f.divider) m[`${b.key}.${ii}.${f.id}`] = f;
      })));
      return m;
    }, [blocks]);
    // a field can only be "keyed in" once it actually has a value — you can't tick a blank
    const valueKeys = allKeys.filter(k => {
      const f = fieldByKey[k];
      return f && String(evOf(f, k)).trim();
    });
    const ticked = valueKeys.filter(k => ticks[k]).length;
    const allTicked = valueKeys.length > 0 && ticked === valueKeys.length;
    // mandatory fields still blank (block the seal)
    const reqLeft = useMemo(() => {
      let n = 0;
      blocks.forEach(b => b.instances.forEach((inst, ii) => (inst.fields || []).forEach(f => {
        if (!f.divider && isMandatory(f) && !String(evOf(f, `${b.key}.${ii}.${f.id}`)).trim()) n++;
      })));
      return n;
    }, [blocks, vals]);
